input.command:
cd /tmp/rv/repo && cat > /tmp/rv/t.bats <<'EOF'
@test x {
  run /tmp/rv/repo/tools/check-round-independence.sh /tmp/rv/repo/tests/fixtures/rounds/independent.md
  echo "status=$status out=$output" >&3
}
EOF
bats /tmp/rv/t.bats

content.content:
67:@test "dec-write new: ids allocate max+1 and print DEC-%04d" {
76:@test "dec-write: the ledger never shrinks and never drops an id across every operation" {
88:@test "dec-write: a failed write leaves the previous file byte-identical (validation refuses the candidate)" {
101:@test "dec-write: an unknown schema_version is refused before any write" {
109:@test "dec-write: the header comment survives a write (yq keeps the head comment)" {
115:@test "dec-write: ids come from the target file only; a populated live ledger does not shift a fresh --file fixture" {
134:@test "dec-write: decide and confirm without --evidence, reject without --rationale or --follow-up exit non-zero" {
147:@test "dec-write: a proposed row needs a decision, a rationale and an alternative" {
155:@test "dec-write: every write lands open or proposed and decided_by stays null" {
162:@test "dec-write decide: open -> proposed appends one transition and sets the decide fields once" {
173:@test "dec-write confirm: only --recorded-by decisions-command may confirm" {
180:@test "dec-write confirm: an operator-kind ref makes decided_by operator; without one decided_by is the proposing voice" {
191:@test "dec-write confirm --cycle: two matches refuse without --all; --all confirms both" {
202:@test "dec-write reject: open/proposed -> rejected records rejection_rationale, follow_up and prior requests" {
210:@test "dec-write reject: an agent cannot reject a decided row; the operator command can" {
220:@test "dec-write supersede (agent): the new row is proposed, the old stays decided with supersede_proposed_by; confirming the new row supersedes the old" {
235:@test "dec-write supersede (operator): the old row moves to superseded and nothing is removed" {
248:@test "dec-write: a ref outside the grammar is refused" {
257:@test "dec-write --as flatline: a missing artifact is refused; an existing one is hashed into evidence_sha256" {
271:@test "dec-write --as dissent: the artifact must be an a2a adversarial-*.json" {
297:@test "dec-write unattended: a RUNNING sprint-plan-state.json forces proposed/agent" {
302:@test "dec-write unattended: a RUNNING .run/state.json forces proposed/agent" {
307:@test "dec-write unattended: a fresh .run/unattended.json forces proposed/agent" {
313:@test "dec-write unattended: LOA_UNATTENDED=1 forces proposed/agent" {
317:@test "dec-write unattended: LOA_FLATLINE_MODE=autonomous forces proposed/agent" {
321:@test "dec-write unattended: a PRD Status line naming an autonomous run forces proposed/agent" {
326:@test "dec-write unattended: the default status is proposed; an explicit --status open stays open" {
333:@test "dec-write context: a stale marker (other session or past the TTL) is ignored" {
346:@test "dec-write context --clear runs only from the operator command" {
354:@test "dec-write confirm: refused under a live-run signal; the PRD Status line alone does not block it" {
370:@test "dec-write: CI, GITHUB_ACTIONS and LOA_HOOK_CONTEXT=1 make a live-ledger write exit 1; --file fixtures still run" {
382:@test "dec-write: the live ledger in the main checkout gets DEC ids; --pending writes the sprint pending file" {
391:@test "dec-write: a linked worktree writes PEND rows to the pending file; import in the main checkout allocates ids, rewrites refs and deletes the file" {
420:@test "dec-write: a held flock makes a second writer exit 1 and leaves the file intact" {
433:@test "dec-write: without flock the mkdir lock refuses a live holder and breaks a stale one" {
444:@test "dec-write: with flock absent from PATH the mkdir lock serialises writers" {
458:@test "dec-write preflight: a missing jq or a non-v4 yq fails closed; a missing br does not" {
472:@test "dec-write: the 160-character summary limit counts characters, not bytes" {
480:@test "dec-write: an unknown flag or command is a usage error (exit 2)" {
491:@test "dec-write: the hostile-string corpus round-trips byte-equal against the sanitised input" {
527:@test "dec-write list: tsv, md (Voice column, confirm line) and json, filtered by status, voice and cycle" {
547:@test "dec-write: no skill grants the operator-only operations in allowed-tools" {
552:@test "dec-write: /decisions is model-uninvocable and the only command or skill passing --recorded-by decisions-command" {
564:@test "dec-write: the ledger is tracked: not ignored by git, any -v match is the negation, and the gitignore-state check is clean" {
548:  run grep -rlE 'dec-write-lib\.sh[^"'"'"']*(confirm|supersede|context --clear)' "$REPO/.claude/skills" --include=SKILL.md
549:  [ "$status" -ne 0 ] || { echo "skills granting operator ops: $output"; return 1; }
553:  local cmd="$REPO/.claude/commands/decisions.md"
558:  run grep -rlF -- '--recorded-by decisions-command' "$REPO/.claude/commands" "$REPO/.claude/skills"

